CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,email TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,platform TEXT NOT NULL,platform_user_id TEXT NOT NULL,display_name TEXT,status TEXT NOT NULL DEFAULT 'connected',access_token_enc TEXT,refresh_token_enc TEXT,expires_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,platform));
CREATE TABLE IF NOT EXISTS layouts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL,document_json TEXT NOT NULL,is_default INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS commands(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL,cost_uc INTEGER NOT NULL DEFAULT 0,cooldown_seconds INTEGER NOT NULL DEFAULT 0,action_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rules(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL,trigger_json TEXT NOT NULL,conditions_json TEXT NOT NULL,actions_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,platform TEXT NOT NULL,type TEXT NOT NULL,event_json TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS balances(user_id TEXT PRIMARY KEY,uc_balance INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
